  var runResponse=call(wf+"/run","POST",Map.of("id",d.id(),"revision",1,"editVersion",0,"digest",d.digest(),"dryRun",true),true);assertEquals(200,runResponse.statusCode(),runResponse.body());var run=CatalogJson.JSON.readTree(runResponse.body());
