  var page=CatalogJson.JSON.readTree(call(outputs+"/workflows/"+d.id()+"/receipts","GET",null,true).body());assertEquals(receipt,page.get("items").get(0));assertFalse(page.get("truncated").asBoolean());
  assertEquals(200,call("/api/v2/data-sources/credentials/"+credential+"/versions/1/revoke","POST",Map.of("requestId",UUID.randomUUID(),"expectedEditVersion",1),true).statusCode());assertEquals(receipt,CatalogJson.JSON.readTree(call(outputs+"/commands/"+requestId,"GET",null,true).body()));assertEquals(receipt,CatalogJson.JSON.readTree(call(outputs,"POST",command,true).body()));assertEquals(before,upstreamReads.get());
