 @Test void metricInventoryPagesPersistAcrossHttpReadsAndRevocationStopsContinuation()throws Exception{
  var credentialId=UUID.randomUUID();assertEquals(200,call("/api/v2/data-sources/credentials","POST",Map.of("requestId",credentialId,"name","Fixture inventory credential","secret",SECRET),true).statusCode());
   var id=UUID.randomUUID();var create=call("/api/v2/data-sources/connections","POST",Map.of("requestId",id,"name","Fixture inventory source","description","Synthetic 45-item source","endpointPin",endpoint(),"credentialPin",new SourceCredential.Pin(credentialId,1,credentialId),"hostGroupIds",List.of("1001")),true);
  assertEquals(200,create.statusCode(),create.body());String digest=CatalogJson.JSON.readTree(create.body()).get("receipt").get("instance").get("connectionDigest").asString(),base="/api/v2/data-sources/"+id;
  var command=new LinkedHashMap<String,Object>();command.put("requestId",UUID.randomUUID());command.put("configurationRevision",1);command.put("connectionDigest",digest);command.put("previousRequestId",null);
  int before=upstreamReads.get();assertEquals(401,call(base+"/metric-discoveries","POST",command,false).statusCode());
  for(var field:List.of("offset","cursor","itemids","tenantId","url","credentialPin")){var bad=new LinkedHashMap<>(command);bad.put(field,"forged");assertEquals(400,call(base+"/metric-discoveries","POST",bad,true).statusCode());}
  assertEquals(400,call(base+"/metric-discoveries?offset=20","POST",command,true).statusCode());assertEquals(before,upstreamReads.get());
  Object previous=null;String root=null;
  for(int page=0;page<3;page++){
   command.put("requestId",UUID.randomUUID());command.put("previousRequestId",previous);var response=call(base+"/metric-discoveries","POST",command,true);assertEquals(200,response.statusCode(),response.body());var receipt=CatalogJson.JSON.readTree(response.body());var inspection=receipt.get("view").get("inspection");var result=inspection.get("metricPage");
   assertEquals("CURRENT",receipt.get("view").get("validity").asString());assertEquals(page*20,result.get("offset").asInt());assertEquals(page==2?5:20,result.get("items").size());assertEquals(page==2,result.get("complete").booleanValue());assertEquals(45,result.get("manifest").get("total").asInt());assertEquals(before+6*(page+1),upstreamReads.get());assertFalse(response.body().contains("metricMembership"));assertFalse(response.body().contains("itemIds"));assertFalse(response.body().contains(SECRET));
   if(root==null)root=result.get("manifest").get("snapshotId").asString();assertEquals(root,result.get("manifest").get("snapshotId").asString());
   assertEquals(receipt,CatalogJson.JSON.readTree(call(base+"/inspections/"+command.get("requestId"),"GET",null,true).body()));assertEquals(receipt,CatalogJson.JSON.readTree(call(base+"/metric-discoveries","POST",command,true).body()));assertEquals(before+6*(page+1),upstreamReads.get());previous=command.get("requestId");
  }
  command.put("requestId",UUID.randomUUID());command.put("previousRequestId",previous);assertEquals(409,call(base+"/metric-discoveries","POST",command,true).statusCode());assertEquals(before+18,upstreamReads.get());
  command.put("previousRequestId",null);var first=call(base+"/metric-discoveries","POST",command,true);assertEquals(200,first.statusCode(),first.body());Object lastRoot=command.get("requestId");int after=upstreamReads.get();
  assertEquals(200,call("/api/v2/data-sources/credentials/"+credentialId+"/versions/1/revoke","POST",Map.of("requestId",UUID.randomUUID(),"expectedEditVersion",1),true).statusCode());
  assertEquals("STALE",CatalogJson.JSON.readTree(call(base+"/inspections/"+lastRoot,"GET",null,true).body()).get("view").get("validity").asString());command.put("requestId",UUID.randomUUID());command.put("previousRequestId",lastRoot);assertEquals(503,call(base+"/metric-discoveries","POST",command,true).statusCode());assertEquals(after,upstreamReads.get());
 }
